export const sourceTerms=[{"topic": "1.1", "term": "Scarcity", "definition": "The basic economic problem that wants and needs exceed available resources."}, {"topic": "1.1", "term": "Economic resources", "definition": "The scarce inputs used to produce goods and services: land, labor, capital, and entrepreneurship."}, {"topic": "1.1", "term": "Land", "definition": "Natural resources used in production, including physical land, minerals, oil, timber, and raw materials."}, {"topic": "1.1", "term": "Labor", "definition": "Human effort, skill, and ability used to produce goods and services."}, {"topic": "1.1", "term": "Capital", "definition": "Produced tools, equipment and structures used in production; distinguish physical capital from human skills."}, {"topic": "1.1", "term": "Entrepreneurship", "definition": "The ability to take risks and combine resources in new ways to produce goods or services."}, {"topic": "1.1", "term": "Ceteris paribus", "definition": "The assumption that all other variables are held constant while one relationship is studied."}, {"topic": "1.2", "term": "Opportunity cost", "definition": "The value of the next-best alternative given up when a choice is made."}, {"topic": "1.2", "term": "Trade-off", "definition": "An alternative use of a scarce resource that must be sacrificed when a choice is made."}, {"topic": "1.2", "term": "Production possibilities curve", "definition": "The boundary of maximum feasible combinations of two outputs with given resources and technology."}, {"topic": "1.2", "term": "Productive efficiency", "definition": "Production with the least waste, represented by points on the PPC."}, {"topic": "1.2", "term": "Underutilized resources", "definition": "Resources are not fully employed, represented by points inside the PPC."}, {"topic": "1.2", "term": "Law of increasing opportunity cost", "definition": "As more of one good is produced, increasing amounts of the other good must be given up."}, {"topic": "1.2", "term": "Economic growth", "definition": "An increase in an economy's productive capacity, shown by an outward shift of the PPC."}, {"topic": "1.3", "term": "Absolute advantage", "definition": "The ability to produce more output with the same resources, or the same output with fewer resources."}, {"topic": "1.3", "term": "Comparative advantage", "definition": "The ability to produce a good or service at a lower opportunity cost than another producer."}, {"topic": "1.3", "term": "Specialization", "definition": "Focusing production on the good or service for which a producer has comparative advantage."}, {"topic": "1.3", "term": "Terms of trade", "definition": "The rate at which two goods are exchanged; mutually beneficial terms lie between opportunity costs."}, {"topic": "1.4", "term": "Demand", "definition": "The willingness and ability of consumers to buy different quantities at different prices."}, {"topic": "1.4", "term": "Law of demand", "definition": "Price and quantity demanded move inversely, creating a downward-sloping demand curve."}, {"topic": "1.4", "term": "Quantity demanded", "definition": "The amount consumers are willing and able to buy at a specific price."}, {"topic": "1.4", "term": "Determinants of demand", "definition": "Non-price factors that shift demand, such as income, tastes, expectations, population, and prices of related goods."}, {"topic": "1.5", "term": "Supply", "definition": "The willingness and ability of producers to sell different quantities at different prices."}, {"topic": "1.5", "term": "Law of supply", "definition": "Price and quantity supplied move directly, creating an upward-sloping supply curve."}, {"topic": "1.5", "term": "Quantity supplied", "definition": "The amount producers are willing and able to sell at a specific price."}, {"topic": "1.5", "term": "Determinants of supply", "definition": "Non-price factors that shift supply, such as input costs, technology, taxes, regulations, competition, and expectations."}, {"topic": "1.6", "term": "Market equilibrium", "definition": "The condition where quantity demanded equals quantity supplied."}, {"topic": "1.6", "term": "Equilibrium price", "definition": "The market-clearing price at which there is no shortage or surplus."}, {"topic": "1.6", "term": "Equilibrium quantity", "definition": "The quantity bought and sold where demand and supply intersect."}, {"topic": "1.6", "term": "Disequilibrium", "definition": "A market condition where quantity demanded and quantity supplied are not equal."}, {"topic": "1.6", "term": "Shortage", "definition": "A disequilibrium condition where quantity demanded is greater than quantity supplied."}, {"topic": "1.6", "term": "Surplus", "definition": "A disequilibrium condition where quantity supplied is greater than quantity demanded."}, {"topic": "2.1", "term": "Circular flow model", "definition": "A model showing how households, firms, government, and the rest of the world exchange resources, products, income, and spending."}, {"topic": "2.1", "term": "Product market", "definition": "The market in which final goods and services are bought and sold."}, {"topic": "2.1", "term": "Factor market", "definition": "The market in which land, labor, capital, and entrepreneurship are bought and sold."}, {"topic": "2.1", "term": "Gross domestic product", "definition": "The market value of all final goods and services produced within a country in a given period."}, {"topic": "2.1", "term": "Final goods and services", "definition": "Output purchased for final use rather than for resale or further production."}, {"topic": "2.1", "term": "Intermediate goods", "definition": "Goods used as inputs in the production of other goods and excluded from GDP to avoid double counting."}, {"topic": "2.1", "term": "Expenditure approach", "definition": "A GDP calculation that adds spending on final output: C + I + G + Xn."}, {"topic": "2.1", "term": "Income approach", "definition": "A GDP calculation that adds income earned in production, including rent, wages, interest, and profit."}, {"topic": "2.1", "term": "Value-added approach", "definition": "A GDP calculation that sums the value added at each stage of production."}, {"topic": "2.1", "term": "Consumption", "definition": "Household purchases of goods and services."}, {"topic": "2.1", "term": "Investment", "definition": "Spending on new capital goods, new construction and changes in inventories."}, {"topic": "2.1", "term": "Government purchases", "definition": "Government spending on goods and services produced in the economy."}, {"topic": "2.1", "term": "Net exports", "definition": "Exports minus imports; also called the balance of trade."}, {"topic": "2.1", "term": "Exports", "definition": "Domestically produced goods and services sold to buyers in other countries."}, {"topic": "2.1", "term": "Imports", "definition": "Goods and services produced abroad and purchased domestically."}, {"topic": "2.2", "term": "Limitations of GDP", "definition": "GDP measures production but misses some well-being factors, nonmarket activity, underground activity, distribution, and environmental costs."}, {"topic": "2.2", "term": "Nonmarket transaction", "definition": "Production that creates value but is not bought or sold in a recorded market."}, {"topic": "2.2", "term": "Underground economy", "definition": "Unreported or illegal production that is not counted in official GDP."}, {"topic": "2.3", "term": "Labor force", "definition": "The employed plus the unemployed in the civilian working-age population."}, {"topic": "2.3", "term": "Unemployment", "definition": "Being jobless while actively looking for work."}, {"topic": "2.3", "term": "Unemployment rate", "definition": "The percentage of the labor force that is unemployed."}, {"topic": "2.3", "term": "Labor force participation rate", "definition": "The labor force divided by the civilian working-age population, multiplied by 100."}, {"topic": "2.3", "term": "Frictional unemployment", "definition": "Short-term unemployment that occurs as workers search for jobs or enter the labor force."}, {"topic": "2.3", "term": "Structural unemployment", "definition": "Unemployment caused by a mismatch between workers' skills or locations and available jobs."}, {"topic": "2.3", "term": "Cyclical unemployment", "definition": "Unemployment caused by downturns in the business cycle."}, {"topic": "2.3", "term": "Natural rate of unemployment", "definition": "The unemployment rate when cyclical unemployment is zero; frictional plus structural unemployment."}, {"topic": "2.3", "term": "Discouraged worker", "definition": "A person available for work who has stopped looking and is not counted as unemployed."}, {"topic": "2.4", "term": "Consumer price index", "definition": "A price index based on the cost of a fixed market basket of consumer goods and services."}, {"topic": "2.4", "term": "Inflation", "definition": "An increase in the overall price level."}, {"topic": "2.4", "term": "Deflation", "definition": "A decrease in the overall price level."}, {"topic": "2.4", "term": "Disinflation", "definition": "A decrease in the inflation rate."}, {"topic": "2.4", "term": "Inflation rate", "definition": "The percentage change in the overall price level or CPI."}, {"topic": "2.4", "term": "Real variables", "definition": "Variables adjusted for inflation, such as real wages, real income, and real GDP."}, {"topic": "2.4", "term": "Substitution bias", "definition": "A CPI problem that can overstate inflation because consumers substitute away from goods that become relatively expensive."}, {"topic": "2.5", "term": "Redistribution effect of inflation", "definition": "Unexpected inflation transfers purchasing power between groups, often from lenders to borrowers."}, {"topic": "2.6", "term": "Nominal GDP", "definition": "GDP measured using current-year prices."}, {"topic": "2.6", "term": "Real GDP", "definition": "GDP measured using base-year prices to remove the effect of inflation."}, {"topic": "2.6", "term": "GDP deflator", "definition": "A price index used to convert nominal GDP to real GDP."}, {"topic": "2.7", "term": "Business cycle", "definition": "The recurring expansion and contraction of aggregate output and employment."}, {"topic": "2.7", "term": "Expansion", "definition": "A phase of the business cycle when real GDP is rising."}, {"topic": "2.7", "term": "Recession", "definition": "A phase of the business cycle when real GDP is falling."}, {"topic": "2.7", "term": "Peak", "definition": "The turning point where expansion ends and recession begins."}, {"topic": "2.7", "term": "Trough", "definition": "The turning point where recession ends and expansion begins."}, {"topic": "2.7", "term": "Output gap", "definition": "The difference between actual real GDP and potential real GDP."}, {"topic": "2.7", "term": "Potential GDP", "definition": "The level of output produced at full employment; also called full-employment output."}, {"topic": "3.1", "term": "Aggregate demand", "definition": "The total demand for an economy's output at different price levels from households, firms, government, and the rest of the world."}, {"topic": "3.1", "term": "Components of AD", "definition": "Consumption, investment, government spending, and net exports."}, {"topic": "3.1", "term": "Real wealth effect", "definition": "As the price level rises, purchasing power falls and quantity of aggregate output demanded falls."}, {"topic": "3.1", "term": "Interest rate effect", "definition": "A higher price level raises nominal interest rates and reduces interest-sensitive spending, especially investment."}, {"topic": "3.1", "term": "Foreign trade effect", "definition": "A higher domestic price level or interest-rate change can reduce net exports by changing relative prices or currency values."}, {"topic": "3.2", "term": "Multiplier effect", "definition": "An initial change in spending causes a larger total change in aggregate demand and real GDP."}, {"topic": "3.2", "term": "Marginal propensity to consume", "definition": "The change in consumption divided by the change in disposable income."}, {"topic": "3.2", "term": "Marginal propensity to save", "definition": "The change in saving divided by the change in disposable income."}, {"topic": "3.2", "term": "Expenditure multiplier", "definition": "The total change in spending from an initial spending change; equal to 1/MPS in the simple model."}, {"topic": "3.2", "term": "Tax multiplier", "definition": "The total change in aggregate demand caused by a change in taxes."}, {"topic": "3.3", "term": "Short run", "definition": "A period when wages and other input prices do not fully adjust to changes in the price level."}, {"topic": "3.3", "term": "Short-run aggregate supply", "definition": "The relationship between the price level and real output supplied when input prices are sticky."}, {"topic": "3.3", "term": "Sticky wages and prices", "definition": "Wages and other input prices that do not immediately adjust to changes in the price level."}, {"topic": "3.4", "term": "Long run", "definition": "A period when wages and other input prices fully adjust to changes in the price level."}, {"topic": "3.4", "term": "Long-run aggregate supply", "definition": "The level of output produced when the economy fully employs its resources, independent of the price level."}, {"topic": "3.5", "term": "AD-AS equilibrium", "definition": "The price level and real GDP where aggregate demand equals short-run aggregate supply."}, {"topic": "3.5", "term": "Short-run equilibrium", "definition": "The current AD-SRAS intersection, which may be below, at, or above full-employment output."}, {"topic": "3.5", "term": "Long-run equilibrium", "definition": "The point where AD, SRAS, and LRAS intersect at full-employment output."}, {"topic": "3.5", "term": "Recessionary gap", "definition": "A situation where actual output is below full-employment output."}, {"topic": "3.5", "term": "Inflationary gap", "definition": "A situation where actual output is above full-employment output."}, {"topic": "3.6", "term": "Demand shock", "definition": "An outside event that shifts aggregate demand."}, {"topic": "3.6", "term": "Supply shock", "definition": "An outside event that shifts short-run aggregate supply."}, {"topic": "3.6", "term": "Demand-pull inflation", "definition": "Inflation caused by an increase in aggregate demand."}, {"topic": "3.6", "term": "Cost-push inflation", "definition": "Inflation caused by a decrease in short-run aggregate supply."}, {"topic": "3.7", "term": "Long-run self-adjustment", "definition": "Wages and input prices adjust over time, shifting SRAS until the economy returns to full-employment output."}, {"topic": "3.8", "term": "Fiscal policy", "definition": "Government policy that stabilizes the economy by changing taxes, government purchases, or transfers."}, {"topic": "3.8", "term": "Expansionary fiscal policy", "definition": "Policy used to increase aggregate demand, typically higher government spending, higher transfers, or lower taxes."}, {"topic": "3.8", "term": "Contractionary fiscal policy", "definition": "Policy used to decrease aggregate demand, typically lower government spending, lower transfers, or higher taxes."}, {"topic": "3.8", "term": "Disposable income", "definition": "Income available for consumption or saving after taxes."}, {"topic": "3.8", "term": "Policy lag", "definition": "The delay in recognizing a problem, deciding on a policy, and having that policy affect the economy."}, {"topic": "3.9", "term": "Automatic stabilizers", "definition": "Tax and transfer systems that moderate the business cycle without new discretionary policy."}, {"topic": "3.9", "term": "Transfer payments", "definition": "Government payments to households or firms that are not made in exchange for current goods or services."}, {"topic": "3.9", "term": "Taxes", "definition": "Required payments to government that reduce disposable income and fund government activity."}, {"topic": "4.1", "term": "Financial asset", "definition": "A paper or electronic claim that stores wealth, such as money, stocks, or bonds."}, {"topic": "4.1", "term": "Liquidity", "definition": "The ease with which an asset can be converted into money."}, {"topic": "4.1", "term": "Rate of return", "definition": "The profit from an investment expressed as a percentage of the amount invested."}, {"topic": "4.1", "term": "Risk", "definition": "The chance that an investment may lose some or all of its value."}, {"topic": "4.1", "term": "Bond", "definition": "A certificate of debt issued by a government or business promising principal and interest payments."}, {"topic": "4.1", "term": "Stock", "definition": "A share of ownership in a corporation."}, {"topic": "4.1", "term": "Bond prices and interest rates", "definition": "Previously issued bond prices and interest rates move in opposite directions."}, {"topic": "4.2", "term": "Nominal interest rate", "definition": "The interest rate paid on a loan or asset before adjusting for inflation."}, {"topic": "4.2", "term": "Real interest rate", "definition": "The nominal interest rate minus the actual inflation rate."}, {"topic": "4.2", "term": "Expected inflation", "definition": "The inflation rate borrowers and lenders anticipate when setting nominal interest rates."}, {"topic": "4.3", "term": "Money", "definition": "Anything generally accepted as a medium of exchange, store of value, and unit of account."}, {"topic": "4.3", "term": "Medium of exchange", "definition": "A function of money that allows it to be used to buy goods and services."}, {"topic": "4.3", "term": "Store of value", "definition": "A function of money that allows purchasing power to be held over time."}, {"topic": "4.3", "term": "Unit of account", "definition": "A function of money that provides a common measure of value."}, {"topic": "4.3", "term": "Currency in circulation", "definition": "Cash held by households, businesses, and government rather than by banks."}, {"topic": "4.3", "term": "Demand deposit", "definition": "A checking account balance that can be used directly for payments."}, {"topic": "4.3", "term": "Money supply", "definition": "The quantity of money available in the economy, commonly including currency and demand deposits."}, {"topic": "4.3", "term": "Monetary base", "definition": "Currency in circulation plus bank reserves."}, {"topic": "4.4", "term": "Bank", "definition": "A firm that accepts deposits, holds reserves, and makes loans."}, {"topic": "4.4", "term": "Bank reserves", "definition": "Currency held in a bank vault or deposited with the central bank."}, {"topic": "4.4", "term": "Required reserves", "definition": "The portion of demand deposits banks must hold and cannot lend."}, {"topic": "4.4", "term": "Excess reserves", "definition": "Reserves beyond required reserves that banks can lend."}, {"topic": "4.4", "term": "Required reserve ratio", "definition": "The percentage of demand deposits that banks must keep as reserves."}, {"topic": "4.4", "term": "Fractional reserve banking", "definition": "A system in which banks hold part of deposits as reserves and lend the rest."}, {"topic": "4.4", "term": "Money multiplier", "definition": "The ratio of money supply to monetary base; 1/required reserve ratio is a simple theoretical maximum under restrictive assumptions."}, {"topic": "4.4", "term": "Asset", "definition": "Something owned or controlled, such as reserves, loans, or securities on a bank balance sheet."}, {"topic": "4.4", "term": "Liability", "definition": "Something owed, such as a bank's obligation to depositors."}, {"topic": "4.5", "term": "Money market", "definition": "The model where money demand and money supply determine the nominal interest rate."}, {"topic": "4.5", "term": "Money demand", "definition": "The public's desire to hold money as a medium of exchange or store of value."}, {"topic": "4.5", "term": "Money supply in the money market", "definition": "The vertical quantity of money supplied by the central bank and banking system in the money market model."}, {"topic": "4.6", "term": "Central bank", "definition": "A government-established institution that regulates banks and conducts monetary policy."}, {"topic": "4.6", "term": "Federal Reserve", "definition": "The central bank of the United States."}, {"topic": "4.6", "term": "Open market operations", "definition": "Central bank buying and selling of government securities to change the monetary base or reserves."}, {"topic": "4.6", "term": "Discount rate", "definition": "The administered interest rate the Federal Reserve charges banks for direct reserve loans."}, {"topic": "4.6", "term": "Administered interest rates", "definition": "Interest rates set directly by the central bank."}, {"topic": "4.6", "term": "Interest on reserve", "definition": "The administered interest rate paid to banks on reserves held at the central bank."}, {"topic": "4.6", "term": "Federal funds rate", "definition": "The overnight interest rate banks charge each other for reserve loans; the U.S. policy rate."}, {"topic": "4.6", "term": "Policy rate", "definition": "The overnight interbank rate targeted by the central bank to influence short-term rates."}, {"topic": "4.6", "term": "Limited reserves", "definition": "A monetary policy framework in which changes in reserves influence the policy rate."}, {"topic": "4.6", "term": "Ample reserves", "definition": "A monetary policy framework in which reserves are abundant, so administered rates guide the policy rate."}, {"topic": "4.7", "term": "Loanable funds market", "definition": "The market where savers and borrowers interact to determine the real interest rate."}, {"topic": "4.7", "term": "National savings", "definition": "The total supply of savings available for investment, including private and public savings in a closed economy."}, {"topic": "4.7", "term": "Private savings", "definition": "Household savings plus firms' retained earnings."}, {"topic": "4.7", "term": "Public savings", "definition": "Government budget surpluses; negative public savings occurs with deficits."}, {"topic": "4.7", "term": "Capital inflow", "definition": "Savings entering a country from abroad."}, {"topic": "4.7", "term": "Capital outflow", "definition": "Savings leaving a country for foreign assets."}, {"topic": "5.1", "term": "Policy mix", "definition": "A combination of fiscal and monetary policy actions used to influence AD, output, price level, and interest rates."}, {"topic": "5.1", "term": "Expansionary policy", "definition": "Fiscal or monetary policy designed to increase aggregate demand and move output toward full employment."}, {"topic": "5.1", "term": "Contractionary policy", "definition": "Fiscal or monetary policy designed to decrease aggregate demand and reduce inflationary pressure."}, {"topic": "5.2", "term": "Short-run Phillips curve", "definition": "A downward-sloping curve showing the short-run trade-off between inflation and unemployment when expectations are constant."}, {"topic": "5.2", "term": "Long-run Phillips curve", "definition": "A vertical curve at the natural rate of unemployment, showing no long-run trade-off between inflation and unemployment."}, {"topic": "5.2", "term": "Natural rate of unemployment", "definition": "The unemployment rate consistent with full employment in the long run."}, {"topic": "5.2", "term": "Inflation expectations", "definition": "What people expect inflation to be; changes in expectations shift the short-run Phillips curve."}, {"topic": "5.2", "term": "Demand shock on SRPC", "definition": "A demand shock causes movement along the short-run Phillips curve."}, {"topic": "5.2", "term": "Supply shock on SRPC", "definition": "A supply shock shifts the short-run Phillips curve."}, {"topic": "5.3", "term": "Money growth", "definition": "Growth in the money supply; its inflation effect also depends on real output and velocity."}, {"topic": "5.3", "term": "Quantity theory of money", "definition": "The idea that MV = PY, so excessive money growth raises the price level."}, {"topic": "5.3", "term": "Income velocity of money", "definition": "The rate at which money is used to purchase final output."}, {"topic": "5.4", "term": "Budget deficit", "definition": "Government spending, transfers, and interest payments greater than tax revenue."}, {"topic": "5.4", "term": "Budget surplus", "definition": "Tax revenue greater than government spending, transfers, and interest payments."}, {"topic": "5.4", "term": "National debt", "definition": "Outstanding accumulated government borrowing, affected by past deficits and surpluses."}, {"topic": "5.5", "term": "Crowding out", "definition": "Government deficit borrowing raises real interest rates and reduces private investment."}, {"topic": "5.6", "term": "Economic growth", "definition": "An increase in real GDP per capita over time, shown by rightward shifts of LRAS and the PPC."}, {"topic": "5.6", "term": "GDP per capita", "definition": "GDP divided by population; use real GDP per capita to compare output per person over time."}, {"topic": "5.6", "term": "Labor productivity", "definition": "Output produced per unit of labor."}, {"topic": "5.6", "term": "Aggregate production function", "definition": "A model showing how labor, capital, and technology combine to produce real GDP."}, {"topic": "5.6", "term": "Capital deepening", "definition": "An increase in physical capital per worker."}, {"topic": "5.6", "term": "Capital formation", "definition": "Investment that increases the stock of physical capital."}, {"topic": "5.6", "term": "Human capital", "definition": "Workers' education, skills, experience, and productive abilities."}, {"topic": "5.6", "term": "Infrastructure", "definition": "Public capital such as roads, bridges, power systems, water systems, and communications networks."}, {"topic": "5.7", "term": "Supply-side fiscal policy", "definition": "Policies that encourage saving, investment, labor productivity, and long-run economic growth."}, {"topic": "6.1", "term": "Balance of payments", "definition": "An accounting system that records a country's international transactions over a period."}, {"topic": "6.1", "term": "Current account", "definition": "The account that records net exports, net income from abroad, and net transfers."}, {"topic": "6.1", "term": "Capital and financial account", "definition": "The account that records financial capital transfers and purchases or sales of assets between countries."}, {"topic": "6.1", "term": "Balance of trade", "definition": "Exports minus imports; the net exports portion of the current account."}, {"topic": "6.1", "term": "Net transfers", "definition": "Transfers received from abroad minus transfers sent abroad."}, {"topic": "6.1", "term": "Financial capital inflow", "definition": "Foreign purchases of domestic financial assets; these are credit entries, not necessarily an overall account surplus."}, {"topic": "6.1", "term": "Financial capital outflow", "definition": "Domestic purchases of foreign financial assets; these are debit entries, not necessarily an overall account deficit."}, {"topic": "6.2", "term": "Exchange rate", "definition": "The value of one country's currency in terms of another country's currency."}, {"topic": "6.2", "term": "Appreciation", "definition": "An increase in a currency’s value relative to another; interpret the quotation units carefully."}, {"topic": "6.2", "term": "Depreciation", "definition": "A decrease in a currency’s value relative to another; interpret the quotation units carefully."}, {"topic": "6.3", "term": "Foreign exchange market", "definition": "The market where currencies are exchanged and equilibrium exchange rates are determined."}, {"topic": "6.3", "term": "Demand for currency", "definition": "Demand arising when foreigners want a country's goods, services, or financial assets."}, {"topic": "6.3", "term": "Supply of currency", "definition": "Supply arising when domestic buyers need foreign currency to buy foreign goods, services, or assets."}, {"topic": "6.3", "term": "Equilibrium exchange rate", "definition": "The exchange rate where quantity of a currency demanded equals quantity supplied."}, {"topic": "6.4", "term": "Tariff", "definition": "A tax on imports."}, {"topic": "6.4", "term": "Quota", "definition": "A legal limit on imports."}, {"topic": "6.5", "term": "Currency value and net exports", "definition": "Currency appreciation tends to reduce net exports; depreciation tends to increase net exports."}, {"topic": "6.6", "term": "Real interest rates and capital flows", "definition": "Financial capital tends to move toward countries with relatively higher real interest rates."}];
export const sourceQuestions=[{"id": "ma-source-MACRO-004", "topic": "1.2", "unit": 1, "skill": "concept", "stem": "If a certain combination of goods or services lies outside the production possibilities curve of an economy, which of the following is true?", "options": [{"key": "A", "text": "Effective trade barriers have reduced foreign imports into the economy.", "error": "C2"}, {"key": "B", "text": "New technology is being used in production.", "error": "C2"}, {"key": "C", "text": "Resources are not available to achieve that combination of goods or services.", "error": null}, {"key": "D", "text": "Resources are not being used efficiently to achieve that combination of goods or services.", "error": "C2"}, {"key": "E", "text": "Resources are being used at a more rapid rate than they were in the past.", "error": "C2"}], "correct": "C", "explanation": "A point outside the PPC is not currently producible with existing resources and technology.", "zh": "正确答案是 C。本题考查机会成本与生产可能性曲线。PPC 外的点在现有资源和技术下不可达到；沿 PPC 移动体现机会成本。 因此“Resources are not available to achieve that combination of goods or services.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-004"}, {"id": "ma-source-MACRO-010", "topic": "1.3", "unit": 1, "skill": "concept", "stem": "If two nations specialize according to their individual comparative advantages and engage in trade, then which of the following must be true?", "options": [{"key": "A", "text": "Nations would be better off if they were self-sufficient.", "error": "C2"}, {"key": "B", "text": "If one nation gains from trade with the other nation, then the other nation will lose.", "error": "C2"}, {"key": "C", "text": "Both nations can consume beyond their individual production possibilities.", "error": null}, {"key": "D", "text": "Both nations can consume only what they produce.", "error": "C2"}, {"key": "E", "text": "Both nations will lose from trade.", "error": "C2"}], "correct": "C", "explanation": "Specialization at comparative advantage and mutually beneficial trade can expand consumption possibilities.", "zh": "正确答案是 C。本题考查比较优势与贸易收益。比较优势取决于较低机会成本，专业化和贸易能让消费组合超出各自 PPC。 因此“Both nations can consume beyond their individual production possibilities.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-010"}, {"id": "ma-source-MACRO-016", "topic": "1.5", "unit": 1, "skill": "concept", "stem": "A leftward shift of the supply curve for computers could be caused by which of the following in the short run?", "options": [{"key": "A", "text": "A decrease in the number of computer manufacturers", "error": null}, {"key": "B", "text": "A decease in taxes on computer manufacturers", "error": "C2"}, {"key": "C", "text": "A decrease in the price of computers", "error": "C2"}, {"key": "D", "text": "A decrease in the price of components used to assemble computers", "error": "C2"}, {"key": "E", "text": "An increase in the price of mobile devices, a substitute good", "error": "C2"}], "correct": "A", "explanation": "Fewer producers reduce market supply at each price.", "zh": "正确答案是 A。本题考查供给。投入成本、税收、技术和卖家数量会移动供给曲线；自身价格变化是沿曲线移动。 因此“A decrease in the number of computer manufacturers”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-016"}, {"id": "ma-source-MACRO-018", "topic": "1.5", "unit": 1, "skill": "concept", "stem": "If the wage rate of workers producing a good decreases, then which of the following will most likely occur?", "options": [{"key": "A", "text": "The demand curve will shift to the right.", "error": "C2"}, {"key": "B", "text": "The supply of the good will increase.", "error": null}, {"key": "C", "text": "The quantity supplied of the good will decrease.", "error": "C2"}, {"key": "D", "text": "Demand for the good will increase", "error": "C2"}, {"key": "E", "text": "Quantity demanded for the good will decrease.", "error": "C2"}], "correct": "B", "explanation": "Lower wages reduce production costs and increase supply.", "zh": "正确答案是 B。本题考查供给。投入成本、税收、技术和卖家数量会移动供给曲线；自身价格变化是沿曲线移动。 因此“The supply of the good will increase.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-018"}, {"id": "ma-source-MACRO-019", "topic": "1.6", "unit": 1, "skill": "concept", "stem": "If there is a decrease in the price of the coffee beans used to make brewed coffee, how will this affect the equilibrium price and quantity of brewed coffee?", "options": [{"key": "A", "text": "Equilibrium price will decrease and equilibrium quantity will increase", "error": null}, {"key": "B", "text": "Equilibrium price will decrease and equilibrium quantity will not change", "error": "C2"}, {"key": "C", "text": "Equilibrium price will decrease and equilibrium quantity will decrease", "error": "C2"}, {"key": "D", "text": "Equilibrium price will increase and equilibrium quantity will decrease", "error": "C2"}, {"key": "E", "text": "Equilibrium price will increase and equilibrium quantity will not change", "error": "C2"}], "correct": "A", "explanation": "Cheaper beans shift coffee supply right, lowering price and raising quantity.", "zh": "正确答案是 A。本题考查市场均衡、非均衡与均衡变化。咖啡豆价格下降会降低 brewed coffee 的生产成本，使供给增加；供给右移会使均衡价格下降、均衡数量增加。 因此“Equilibrium price will decrease and equilibrium quantity will increase”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-019"}, {"id": "ma-source-MACRO-026", "topic": "2.1", "unit": 2, "skill": "concept", "stem": "The circular flow model indicates that final goods are produced by", "options": [{"key": "A", "text": "firms and sold in the factor market", "error": "C2"}, {"key": "B", "text": "firms and sold in the product market", "error": null}, {"key": "C", "text": "firms and sold in the resource market", "error": "C2"}, {"key": "D", "text": "households and sold in the factor market", "error": "C2"}, {"key": "E", "text": "households and sold in the product market", "error": "C2"}], "correct": "B", "explanation": "Firms produce final goods and sell them in product markets; factor markets trade inputs.", "zh": "正确答案是 B。本题考查循环流量模型与 GDP。GDP 衡量国内最终产品与服务的市场价值；支出等于收入。 因此“firms and sold in the product market”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-026"}, {"id": "ma-source-MACRO-028", "topic": "2.1", "unit": 2, "skill": "concept", "stem": "An increase in inventories will increase which component of gross domestic product?", "options": [{"key": "A", "text": "Personal consumption expenditures", "error": "C2"}, {"key": "B", "text": "Investment expenditures", "error": null}, {"key": "C", "text": "Government purchases", "error": "C2"}, {"key": "D", "text": "exports", "error": "C2"}, {"key": "E", "text": "Imports", "error": "C2"}], "correct": "B", "explanation": "Inventory accumulation is investment, including unsold newly produced output.", "zh": "正确答案是 B。本题考查循环流量模型与 GDP。GDP 衡量国内最终产品与服务的市场价值；支出等于收入。 因此“Investment expenditures”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-028"}, {"id": "ma-source-MACRO-033", "topic": "2.2", "unit": 2, "skill": "concept", "stem": "GDP does NOT account for which of the following?", "options": [{"key": "A", "text": "The value added by all firms in the economy", "error": "C2"}, {"key": "B", "text": "The depletion of natural resources", "error": null}, {"key": "C", "text": "Wages, rent, profit, and interest payments", "error": "C2"}, {"key": "D", "text": "The value of final goods and services produced domestically", "error": "C2"}, {"key": "E", "text": "Imports from foreign countries", "error": "C2"}], "correct": "B", "explanation": "GDP does not subtract resource depletion as a loss of natural wealth.", "zh": "正确答案是 B。本题考查GDP 的局限。GDP 不直接反映资源耗竭、环境质量、收入分配、非市场活动等。 因此“The depletion of natural resources”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-033"}, {"id": "ma-source-MACRO-035", "topic": "2.1", "unit": 2, "skill": "calculation", "stem": "GDP is $10 million, consumer spending is $6 million, government spending is $3 million, exports are $2 million, and imports are $3 million. How much is spent for investments?", "options": [{"key": "A", "text": "$0 million", "error": "C2"}, {"key": "B", "text": "$1 million", "error": "C2"}, {"key": "C", "text": "$2 million", "error": null}, {"key": "D", "text": "$3 million", "error": "C2"}, {"key": "E", "text": "$4 million", "error": "C2"}], "correct": "C", "explanation": "I = GDP − C − G − X + M = 10 − 6 − 3 − 2 + 3 = 2 million.", "zh": "根据 GDP=C+I+G+X−M，投资为 10−6−3−2+3=2 百万。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-035"}, {"id": "ma-source-MACRO-036", "topic": "2.6", "unit": 2, "skill": "calculation", "stem": "If Real GDP= $200 billion and the GDP deflator (base year = 100)= 200, Nominal GDP is", "options": [{"key": "A", "text": "$4 billion.", "error": "C2"}, {"key": "B", "text": "$400 billion.", "error": null}, {"key": "C", "text": "$200 billion.", "error": "C2"}, {"key": "D", "text": "$2 billion.", "error": "C2"}, {"key": "E", "text": "impossible to determine since the base year is not given", "error": "C2"}], "correct": "B", "explanation": "Nominal GDP = real GDP × GDP deflator / 100 = 200 × 200 / 100 = 400 billion.", "zh": "名义 GDP=实际 GDP×GDP 平减指数/100=400 十亿。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-036"}, {"id": "ma-source-MACRO-040", "topic": "2.3", "unit": 2, "skill": "concept", "stem": "Which of the following individuals is considered officially unemployed?", "options": [{"key": "A", "text": "Chris, who has not worked for more than three years and has given up looking for work", "error": "C2"}, {"key": "B", "text": "Kim, who is going to school full-time and is waiting until graduation before looking for a job", "error": "C2"}, {"key": "C", "text": "Pat, who recently left a job to look for a different job in another town", "error": null}, {"key": "D", "text": "Leslie, who retired after turning 65 only five months ago", "error": "C2"}, {"key": "E", "text": "Lee, who is working 20 hours per week and is seeking full-time employment", "error": "C2"}], "correct": "C", "explanation": "Someone without work who is actively seeking a job is unemployed; part-time workers are employed.", "zh": "正确答案是 C。本题考查失业。官方失业者必须没有工作、正在找工作且愿意工作；摩擦性失业来自换工作或求职匹配过程。 因此“Pat, who recently left a job to look for a different job in another town”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-040"}, {"id": "ma-source-MACRO-041", "topic": "2.3", "unit": 2, "skill": "concept", "stem": "Olivia volunteers full time at an animal shelter and will not accept any offers for a paid job for the next six months. Olivia is", "options": [{"key": "A", "text": "cyclically unemployed", "error": "C2"}, {"key": "B", "text": "not in the labor force", "error": null}, {"key": "C", "text": "employed", "error": "C2"}, {"key": "D", "text": "structurally unemployed", "error": "C2"}, {"key": "E", "text": "a seasonal worker", "error": "C2"}], "correct": "B", "explanation": "Olivia is neither in paid employment nor available for paid work, so is outside the labor force.", "zh": "正确答案是 B。本题考查失业。官方失业者必须没有工作、正在找工作且愿意工作；摩擦性失业来自换工作或求职匹配过程。 因此“not in the labor force”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-041"}, {"id": "ma-source-MACRO-047", "topic": "2.4", "unit": 2, "skill": "calculation", "stem": "If the consumer price index (CPI) in 2001 was 200 and the CPI in 2002 was 215, the rate of inflation was", "options": [{"key": "A", "text": "215%.", "error": "C2"}, {"key": "B", "text": "15%.", "error": "C2"}, {"key": "C", "text": "5%.", "error": "C2"}, {"key": "D", "text": "7.5%.", "error": null}, {"key": "E", "text": "8%.", "error": "C2"}], "correct": "D", "explanation": "Inflation = (215 − 200) / 200 × 100 = 7.5%.", "zh": "正确答案是 D。本题考查价格指数与通货膨胀。CPI 等于当前篮子成本除以基期篮子成本再乘 100；通胀率看指数百分比变化。 因此“7.5%.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-047"}, {"id": "ma-source-MACRO-049", "topic": "2.4", "unit": 2, "skill": "calculation", "stem": "In 2017 Sabrina earned an annual salary of $100,000 as an engineer. In 2018, her income rose to $105,000. The inflation rate in 2018 was 2%. How did Sabrina’s nominal income and real income change in 2018 compared to 2017?", "options": [{"key": "A", "text": "Nominal income decreased and real income decreased.", "error": "C2"}, {"key": "B", "text": "Nominal income decreased and real income did not change.", "error": "C2"}, {"key": "C", "text": "Nominal income increased and real income decreased.", "error": "C2"}, {"key": "D", "text": "Nominal income increased and real income did not change.", "error": "C2"}, {"key": "E", "text": "Nominal income increased and real income increased.", "error": null}], "correct": "E", "explanation": "Nominal income rises 5%, exceeding 2% inflation. Real income rises by 1.05/1.02 − 1, about 2.94%.", "zh": "正确答案是 E。本题考查价格指数与通货膨胀。CPI 等于当前篮子成本除以基期篮子成本再乘 100；通胀率看指数百分比变化。 因此“Nominal income increased and real income increased.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-049"}, {"id": "ma-source-MACRO-051", "topic": "2.5", "unit": 2, "skill": "concept", "stem": "Which of the following would most likely benefit from unexpected deflation?", "options": [{"key": "A", "text": "Lenders", "error": null}, {"key": "B", "text": "Borrowers", "error": "C2"}, {"key": "C", "text": "Retail shop owners", "error": "C2"}, {"key": "D", "text": "Governments in debt", "error": "C2"}, {"key": "E", "text": "Automobile manufacturing firms", "error": "C2"}], "correct": "A", "explanation": "Unexpected deflation raises the real value of fixed nominal repayments received by lenders.", "zh": "正确答案是 A。本题考查通胀成本。固定利率下，实际通胀高于预期通常利好借款人；低于预期则利好贷款人。 因此“Lenders”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-051"}, {"id": "ma-source-MACRO-057", "topic": "3.1", "unit": 3, "skill": "concept", "stem": "Which of the following is a reason why the aggregate demand curve is downward sloping?", "options": [{"key": "A", "text": "A higher price level decreases savings.", "error": "C2"}, {"key": "B", "text": "A higher price level decreases interest rates.", "error": "C2"}, {"key": "C", "text": "A higher price level increases exports.", "error": "C2"}, {"key": "D", "text": "A higher price level decreases imports.", "error": "C2"}, {"key": "E", "text": "A higher price level decreases real wealth.", "error": null}], "correct": "E", "explanation": "Higher prices reduce the purchasing power of nominal wealth, reducing real consumption demand.", "zh": "正确答案是 E。本题考查总需求。价格水平上升会降低真实财富、提高利率并减少净出口，因此 AD 向下倾斜。 因此“A higher price level decreases real wealth.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-057"}, {"id": "ma-source-MACRO-061", "topic": "3.2", "unit": 3, "skill": "calculation", "stem": "Suppose that autonomous consumption is $400 and that the marginal propensity to consume is 0.8. If disposable income increases by $1,200, consumption spending will increase by", "options": [{"key": "A", "text": "$1,600", "error": "C2"}, {"key": "B", "text": "$1,360", "error": "C2"}, {"key": "C", "text": "$1,200", "error": "C2"}, {"key": "D", "text": "$960", "error": null}, {"key": "E", "text": "$400", "error": "C2"}], "correct": "D", "explanation": "The change in consumption is MPC × change in income = 0.8 × 1200 = 960; autonomous consumption is unchanged.", "zh": "正确答案是 D。本题考查乘数。简单支出乘数为 1/MPS，税收乘数为 -MPC/MPS。 因此“$960”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-061"}, {"id": "ma-source-MACRO-063", "topic": "3.2", "unit": 3, "skill": "calculation", "stem": "In a closed economy with only lump-sum taxation, if the marginal propensity to consume is equal to 0.75, a $70 billion increase in government spending could cause a maximum increase in output of", "options": [{"key": "A", "text": "$52.5 billion", "error": "C2"}, {"key": "B", "text": "$70 billion", "error": "C2"}, {"key": "C", "text": "$122.5 billion", "error": "C2"}, {"key": "D", "text": "$210 billion", "error": "C2"}, {"key": "E", "text": "$280 billion", "error": null}], "correct": "E", "explanation": "The simple multiplier is 1/(1−0.75)=4, so 70 × 4 = 280 billion.", "zh": "正确答案是 E。本题考查乘数。简单支出乘数为 1/MPS，税收乘数为 -MPC/MPS。 因此“$280 billion”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-063"}, {"id": "ma-source-MACRO-067", "topic": "3.2", "unit": 3, "skill": "calculation", "stem": "Assume the marginal propensity to consume is 0.8. How will a decrease in taxes of $100 billion and a decrease in government spending of $100 billion affect aggregate demand?", "options": [{"key": "A", "text": "Aggregate demand will decrease by $900 billion.", "error": "C2"}, {"key": "B", "text": "Aggregate demand will decrease by $500 billion.", "error": "C2"}, {"key": "C", "text": "Aggregate demand will decrease by $400 billion.", "error": "C2"}, {"key": "D", "text": "Aggregate demand will decrease by $100 billion.", "error": null}, {"key": "E", "text": "Aggregate demand will not change.", "error": "C2"}], "correct": "D", "explanation": "The spending multiplier is 5 and tax multiplier −4: 5(−100) + (−4)(−100) = −100 billion.", "zh": "正确答案是 D。本题考查乘数。简单支出乘数为 1/MPS，税收乘数为 -MPC/MPS。 因此“Aggregate demand will decrease by $100 billion.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-067"}, {"id": "ma-source-MACRO-070", "topic": "3.3", "unit": 3, "skill": "concept", "stem": "Which of the following will cause a rightward shift of the short-run aggregate supply curve?", "options": [{"key": "A", "text": "An increase in consumption spending", "error": "C2"}, {"key": "B", "text": "An increase in nominal wages", "error": "C2"}, {"key": "C", "text": "An increase in income taxes", "error": "C2"}, {"key": "D", "text": "A decrease in the price level", "error": "C2"}, {"key": "E", "text": "A decrease in the costs of production", "error": null}], "correct": "E", "explanation": "Lower production costs permit greater output at every price level, shifting SRAS right.", "zh": "正确答案是 E。本题考查短期总供给。生产成本下降使 SRAS 右移；能源或工资成本上升使 SRAS 左移。 因此“A decrease in the costs of production”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-070"}, {"id": "ma-source-MACRO-074", "topic": "3.4", "unit": 3, "skill": "concept", "stem": "Which of the following must be true in the long run?", "options": [{"key": "A", "text": "Production increases when prices increase.", "error": "C2"}, {"key": "B", "text": "An increase in the price level reduces aggregate demand.", "error": "C2"}, {"key": "C", "text": "The natural rate of unemployment is not affected by changes in production capacity.", "error": "C2"}, {"key": "D", "text": "Full employment increases when price level decreases.", "error": "C2"}, {"key": "E", "text": "Prices and wages are flexible", "error": null}], "correct": "E", "explanation": "The macroeconomic long run allows prices and wages to adjust fully.", "zh": "正确答案是 E。本题考查长期总供给。长期中工资和价格具有弹性，产出回到潜在产出。 因此“Prices and wages are flexible”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-074"}, {"id": "ma-source-MACRO-075", "topic": "3.6", "unit": 3, "skill": "concept", "stem": "Which of the following changes will necessarily cause inflation?", "options": [{"key": "A", "text": "A decrease in aggregate demand and a decrease in short-run aggregate supply.", "error": "C2"}, {"key": "B", "text": "A decrease in aggregate demand and an increase in short-run aggregate supply.", "error": "C2"}, {"key": "C", "text": "A decrease in aggregate demand with no change in short-run aggregate supply.", "error": "C2"}, {"key": "D", "text": "An increase in aggregate demand and a decrease in short-run aggregate supply.", "error": null}, {"key": "E", "text": "An increase in aggregate demand and an increase in short-run aggregate supply", "error": "C2"}], "correct": "D", "explanation": "Increasing AD and decreasing SRAS both raise the equilibrium price level; output is ambiguous.", "zh": "正确答案是 D。本题考查AD-AS 短期变化。AD 右移通常提高产出和价格、降低失业；SRAS 左移会造成滞胀。 因此“An increase in aggregate demand and a decrease in short-run aggregate supply.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-075"}, {"id": "ma-source-MACRO-085", "topic": "3.4", "unit": 3, "skill": "concept", "stem": "Which of the following explains why the long-run aggregate supply curve corresponds to the production possibilities curve?", "options": [{"key": "A", "text": "Both curves are downward sloping.", "error": "C2"}, {"key": "B", "text": "Both curves illustrate flexible wages and prices.", "error": "C2"}, {"key": "C", "text": "Both curves illustrate the maximum sustainable capacity.", "error": null}, {"key": "D", "text": "Both curves illustrate the trade-off between inflation and unemployment.", "error": "C2"}, {"key": "E", "text": "Both curves illustrate short-run macroeconomic equilibrium", "error": "C2"}], "correct": "C", "explanation": "Both LRAS and the PPC represent sustainable productive capacity.", "zh": "正确答案是 C。本题考查长期总供给。LRAS 和 PPC 都表示经济在资源和技术约束下的最大可持续产能，因此二者对应的是 maximum sustainable capacity。 因此“Both curves illustrate the maximum sustainable capacity.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-085"}, {"id": "ma-source-MACRO-088", "topic": "3.5", "unit": 3, "skill": "concept", "stem": "In the AD-AS model, which of the following is true?", "options": [{"key": "A", "text": "The economy is in an inflationary gap when the short-run equilibrium real output is below the long-run equilibrium real output.", "error": "C2"}, {"key": "B", "text": "The economy is in an inflationary gap when the short-run equilibrium real output is at the long-run equilibrium real output.", "error": "C2"}, {"key": "C", "text": "The economy is in a recessionary gap when the short-run equilibrium real output is at the long-run equilibrium real output.", "error": "C2"}, {"key": "D", "text": "The economy is in a recessionary gap when the short-run equilibrium real output is below the long-run equilibrium real output.", "error": null}, {"key": "E", "text": "The economy is in a recessionary gap when the short-run equilibrium real output is above the long-run equilibrium real output.", "error": "C2"}], "correct": "D", "explanation": "A recessionary gap means actual equilibrium output is below potential output.", "zh": "衰退缺口表示实际均衡产出低于潜在产出。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-088"}, {"id": "ma-source-MACRO-095", "topic": "3.7", "unit": 3, "skill": "concept", "stem": "An economy is currently in short-run equilibrium, and real output is below the full-employment level of output. Which of the following market adjustments is most likely to occur in the long run?", "options": [{"key": "A", "text": "The recessionary gap will create upward pressure on prices, shifting the aggregate demand curve to the left.", "error": "C2"}, {"key": "B", "text": "The existence of cyclical unemployment will increase consumption spending and increase real output.", "error": "C2"}, {"key": "C", "text": "Full-employment output will fall to equal the short-run equilibrium real output.", "error": "C2"}, {"key": "D", "text": "Nominal wages will fall, shifting the short-run aggregate supply curve to the right.", "error": null}, {"key": "E", "text": "Input prices will increase as firms compete for labor and capital.", "error": "C2"}], "correct": "D", "explanation": "Slack labor markets put downward pressure on nominal wages, reducing costs and shifting SRAS right.", "zh": "正确答案是 D。本题考查长期自我调整。长期自我调整通过工资和投入价格改变 SRAS，使产出回到潜在产出；衰退缺口下工资下降、SRAS 右移，通胀缺口下工资上升、SRAS 左移。 因此“Nominal wages will fall, shifting the short-run aggregate supply curve to the right.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-095"}, {"id": "ma-source-MACRO-099", "topic": "3.8", "unit": 3, "skill": "concept", "stem": "Which of the following is an example of an expansionary fiscal policy?", "options": [{"key": "A", "text": "An increase in income tax rates", "error": "C2"}, {"key": "B", "text": "An increase in government expenditures", "error": null}, {"key": "C", "text": "A decrease in transfer payments", "error": "C2"}, {"key": "D", "text": "An increase in the price level", "error": "C2"}, {"key": "E", "text": "An increase in consumption spending", "error": "C2"}], "correct": "B", "explanation": "Higher government purchases directly increase aggregate demand.", "zh": "正确答案是 B。本题考查财政政策。减税或增加政府支出会扩大 AD，短期提高产出、降低失业。 因此“An increase in government expenditures”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-099"}, {"id": "ma-source-MACRO-102", "topic": "4.1", "unit": 4, "skill": "concept", "stem": "Which of the following is considered the most liquid asset?", "options": [{"key": "A", "text": "Stocks", "error": "C2"}, {"key": "B", "text": "Bonds", "error": "C2"}, {"key": "C", "text": "Currency", "error": null}, {"key": "D", "text": "Real estate", "error": "C2"}, {"key": "E", "text": "Commodities", "error": "C2"}], "correct": "C", "explanation": "Currency can be used immediately for payment without selling another asset.", "zh": "正确答案是 C。本题考查金融资产。债券是付息资产；货币通常流动性最高。 因此“Currency”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-102"}, {"id": "ma-source-MACRO-103", "topic": "4.2", "unit": 4, "skill": "concept", "stem": "If the interest rate on loans before adjusting for inflation is 9%, and the expected inflation rate is 4%, then which of the following must be true?", "options": [{"key": "A", "text": "Lenders are expected to receive an additional 4% on their loaned funds.", "error": "C2"}, {"key": "B", "text": "Borrowers are expected to pay an additional 4% on their borrowed funds.", "error": "C2"}, {"key": "C", "text": "The expected real interest rate is 9%.", "error": "C2"}, {"key": "D", "text": "The expected real interest rate is 13%.", "error": "C2"}, {"key": "E", "text": "The nominal interest rate is 9%.", "error": null}], "correct": "E", "explanation": "The stated unadjusted rate is the nominal rate, 9%; the approximate expected real rate is 5%.", "zh": "正确答案是 E。本题考查名义利率与实际利率。实际利率约等于名义利率减预期通胀率。 因此“The nominal interest rate is 9%.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-103"}, {"id": "ma-source-MACRO-106", "topic": "4.3", "unit": 4, "skill": "concept", "stem": "Which of the following is NOT a function of fiat money？", "options": [{"key": "A", "text": "A standard of deferred payment", "error": "C2"}, {"key": "B", "text": "A unit of account", "error": "C2"}, {"key": "C", "text": "A source of intrinsic value", "error": null}, {"key": "D", "text": "A store of value", "error": "C2"}, {"key": "E", "text": "A medium of exchange", "error": "C2"}], "correct": "C", "explanation": "Fiat money does not require intrinsic commodity value to perform its monetary functions.", "zh": "正确答案是 C。本题考查货币定义、衡量与职能。价格标签体现货币的计价单位职能；交易需求体现交换媒介职能。 因此“A source of intrinsic value”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-106"}, {"id": "ma-source-MACRO-108", "topic": "4.3", "unit": 4, "skill": "concept", "stem": "A barter economy is different from a money economy in that a barter economy", "options": [{"key": "A", "text": "encourages specialization and division of labor", "error": "C2"}, {"key": "B", "text": "involves higher costs for each transaction", "error": null}, {"key": "C", "text": "eliminates the need for a double coincidence of wants", "error": "C2"}, {"key": "D", "text": "has only a few assets that serve as a medium of exchange", "error": "C2"}, {"key": "E", "text": "promotes market exchanges", "error": "C2"}], "correct": "B", "explanation": "Barter requires matching each trader’s wants, raising transaction costs.", "zh": "正确答案是 B。本题考查货币定义、衡量与职能。价格标签体现货币的计价单位职能；交易需求体现交换媒介职能。 因此“involves higher costs for each transaction”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-108"}, {"id": "ma-source-MACRO-118", "topic": "4.5", "unit": 4, "skill": "concept", "stem": "The transaction demand for money is very closely associated with money's use as a", "options": [{"key": "A", "text": "store of value", "error": "C2"}, {"key": "B", "text": "standard unit of account", "error": "C2"}, {"key": "C", "text": "measure of value", "error": "C2"}, {"key": "D", "text": "medium of exchange", "error": null}, {"key": "E", "text": "standard of deferred payment", "error": "C2"}], "correct": "D", "explanation": "Transaction balances are held to make payments, which is the medium-of-exchange function.", "zh": "正确答案是 D。本题考查货币市场。利率上升提高持有货币的机会成本，货币需求量下降。 因此“medium of exchange”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-118"}, {"id": "ma-source-MACRO-124", "topic": "4.6", "unit": 4, "skill": "concept", "stem": "Assuming a banking system with limited reserves, which of the following represents an expansionary monetary policy action?", "options": [{"key": "A", "text": "An increase in government spending", "error": "C2"}, {"key": "B", "text": "An increase in the nominal interest rate", "error": "C2"}, {"key": "C", "text": "An increase in the discount rate", "error": "C2"}, {"key": "D", "text": "A decrease in income taxes", "error": "C2"}, {"key": "E", "text": "A decrease in the required reserve ratio", "error": null}], "correct": "E", "explanation": "In the specified limited-reserves model, a lower reserve requirement allows more deposit expansion.", "zh": "正确答案是 E。本题考查货币政策。扩张性货币政策会降低利率或增加货币供给，使投资和 AD 增加；紧缩性货币政策则使 AD 减少。 因此“A decrease in the required reserve ratio”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-124"}, {"id": "ma-source-MACRO-125", "topic": "4.6", "unit": 4, "skill": "concept", "stem": "Assuming a banking system with limited reserves, which of the following is a monetary policy action a central bank would implement to control inflation?", "options": [{"key": "A", "text": "Target a lower overnight interbank lending rate", "error": "C2"}, {"key": "B", "text": "Sell government bonds to the public", "error": null}, {"key": "C", "text": "Lower the discount rate", "error": "C2"}, {"key": "D", "text": "Lower the required reserve ratio", "error": "C2"}, {"key": "E", "text": "Increase the monetary base", "error": "C2"}], "correct": "B", "explanation": "Selling bonds drains reserves and restrains money creation in the specified limited-reserves model.", "zh": "正确答案是 B。本题考查货币政策。扩张性货币政策会降低利率或增加货币供给，使投资和 AD 增加；紧缩性货币政策则使 AD 减少。 因此“Sell government bonds to the public”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-125"}, {"id": "ma-source-MACRO-134", "topic": "4.6", "unit": 4, "skill": "calculation", "stem": "In a banking system with limited reserves, if the reserve requirement is 25 percent and banks hold no excess reserves, an open market sale of $400,000 of government securities by the Federal Reserve will", "options": [{"key": "A", "text": "increase the money supply by up to $1.6 million", "error": "C2"}, {"key": "B", "text": "decrease the money supply by up to $1.6 million", "error": null}, {"key": "C", "text": "increase the money supply by up to $300,000", "error": "C2"}, {"key": "D", "text": "Increase the money supply by up to $100,000", "error": "C2"}, {"key": "E", "text": "decrease the money supply by up to $100,000", "error": "C2"}], "correct": "B", "explanation": "Under the specified simple limited-reserves assumptions, 1/0.25 = 4 and 400000 × 4 = 1.6 million of maximum contraction.", "zh": "正确答案是 B。本题考查货币政策。扩张性货币政策会降低利率或增加货币供给，使投资和 AD 增加；紧缩性货币政策则使 AD 减少。 因此“decrease the money supply by up to $1.6 million”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-134"}, {"id": "ma-source-MACRO-137", "topic": "4.6", "unit": 4, "skill": "concept", "stem": "Which of the following represents a contractionary monetary policy action for a central bank operating in a banking system with ample reserves?", "options": [{"key": "A", "text": "Open market sales", "error": "C2"}, {"key": "B", "text": "Open market purchases", "error": "C2"}, {"key": "C", "text": "Increasing administered interest rates", "error": null}, {"key": "D", "text": "Increasing the required reserve ratio", "error": "C2"}, {"key": "E", "text": "Increasing income taxes", "error": "C2"}], "correct": "C", "explanation": "With ample reserves, higher administered rates guide market rates upward and restrain spending.", "zh": "正确答案是 C。本题考查货币政策。扩张性货币政策会降低利率或增加货币供给，使投资和 AD 增加；紧缩性货币政策则使 AD 减少。 因此“Increasing administered interest rates”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-137"}, {"id": "ma-source-MACRO-139", "topic": "4.6", "unit": 4, "skill": "concept", "stem": "If the Federal Reserve lowers its administered interest rates, which of the following would most likely occur?", "options": [{"key": "A", "text": "Imports will rise, decreasing the trade deficit.", "error": "C2"}, {"key": "B", "text": "The rate of saving will increase.", "error": "C2"}, {"key": "C", "text": "Unemployment and inflation will both increase.", "error": "C2"}, {"key": "D", "text": "Businesses will purchase more factories and equipment.", "error": null}, {"key": "E", "text": "The budget deficit will increase.", "error": "C2"}], "correct": "D", "explanation": "Lower borrowing costs encourage investment in new factories and equipment, other things equal.", "zh": "正确答案是 D。本题考查货币政策。扩张性货币政策会降低利率或增加货币供给，使投资和 AD 增加；紧缩性货币政策则使 AD 减少。 因此“Businesses will purchase more factories and equipment.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-139"}, {"id": "ma-source-MACRO-143", "topic": "4.7", "unit": 4, "skill": "concept", "stem": "Which of the following changes in the loanable funds market will decrease the equilibrium real interest rate?", "options": [{"key": "A", "text": "A decrease in private savings", "error": "C2"}, {"key": "B", "text": "A decrease in the expected inflation rate", "error": "C2"}, {"key": "C", "text": "An increase in government spending on highways financed by borrowing", "error": "C2"}, {"key": "D", "text": "An increase in foreign financial capital inflows", "error": null}, {"key": "E", "text": "An investment tax credit for plant and equipment", "error": "C2"}], "correct": "D", "explanation": "Foreign capital inflow adds funds available to borrowers, lowering the real equilibrium rate.", "zh": "正确答案是 D。本题考查可贷资金市场。资本流入增加可贷资金供给，均衡实际利率下降。 因此“An increase in foreign financial capital inflows”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-143"}, {"id": "ma-source-MACRO-148", "topic": "5.2", "unit": 5, "skill": "concept", "stem": "A short-run Phillips curve shows an inverse relationship between", "options": [{"key": "A", "text": "interest rates and borrowing", "error": "C2"}, {"key": "B", "text": "inflation and unemployment", "error": null}, {"key": "C", "text": "income and consumption", "error": "C2"}, {"key": "D", "text": "prices and quantity demanded", "error": "C2"}, {"key": "E", "text": "inputs and outputs", "error": "C2"}], "correct": "B", "explanation": "The SRPC relates inflation inversely to unemployment for given inflation expectations.", "zh": "正确答案是 B。本题考查菲利普斯曲线。短期菲利普斯曲线显示通胀与失业的反向关系；AD 变化通常沿同一 SRPC 移动。 因此“inflation and unemployment”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-148"}, {"id": "ma-source-MACRO-150", "topic": "5.3", "unit": 5, "skill": "calculation", "stem": "Given a constant velocity of money, in the short run a 5 percent increase in money supply will translate to a 5 percent increase in", "options": [{"key": "A", "text": "government budget deficit", "error": "C2"}, {"key": "B", "text": "real gross domestic product", "error": "C2"}, {"key": "C", "text": "nominal gross domestic product", "error": null}, {"key": "D", "text": "real interest rates", "error": "C2"}, {"key": "E", "text": "nominal interest rates", "error": "C2"}], "correct": "C", "explanation": "With V fixed, MV=PY implies nominal GDP (PY) rises 5%. This does not determine real GDP alone.", "zh": "正确答案是 C。本题考查货币增长与通胀。在货币流通速度不变时，货币供给增长会推高名义 GDP。 因此“nominal gross domestic product”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-150"}, {"id": "ma-source-MACRO-152", "topic": "5.4", "unit": 5, "skill": "concept", "stem": "Which of the following is true about a country’s national debt?", "options": [{"key": "A", "text": "It is the sum of the country’s trade deficit and government budget deficit.", "error": "C2"}, {"key": "B", "text": "It increases when gross domestic product increases.", "error": "C2"}, {"key": "C", "text": "It increases when the country’s government has a budget deficit.", "error": null}, {"key": "D", "text": "It decreases when the country’s exports exceed its imports.", "error": "C2"}, {"key": "E", "text": "It decreases when national savings decrease.", "error": "C2"}], "correct": "C", "explanation": "A deficit financed by borrowing adds to outstanding government debt, other things equal.", "zh": "正确答案是 C。本题考查政府赤字与国债。预算赤字会增加国债；经济扩张通常税收增加、福利支出减少。 因此“It increases when the country’s government has a budget deficit.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-152"}, {"id": "ma-source-MACRO-153", "topic": "5.5", "unit": 5, "skill": "concept", "stem": "An increase in the government budget deficit is most likely to result in an increase in which of the following?", "options": [{"key": "A", "text": "The marginal propensity to consume", "error": "C2"}, {"key": "B", "text": "Exports", "error": "C2"}, {"key": "C", "text": "The real interest rate", "error": null}, {"key": "D", "text": "The money supply", "error": "C2"}, {"key": "E", "text": "The simple multiplier", "error": "C2"}], "correct": "C", "explanation": "Deficit borrowing raises demand for funds and can raise real interest rates.", "zh": "正确答案是 C。本题考查挤出效应。政府赤字增加可贷资金需求，通常提高实际利率。 因此“The real interest rate”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-153"}, {"id": "ma-source-MACRO-155", "topic": "5.7", "unit": 5, "skill": "concept", "stem": "An increase in which of the following is most likely to promote economic growth?", "options": [{"key": "A", "text": "Consumption spending", "error": "C2"}, {"key": "B", "text": "Investment tax credits", "error": null}, {"key": "C", "text": "The natural rate of unemployment", "error": "C2"}, {"key": "D", "text": "The trade deficit", "error": "C2"}, {"key": "E", "text": "Real interest rates", "error": "C2"}], "correct": "B", "explanation": "Investment tax credits encourage capital formation and can raise productive capacity.", "zh": "正确答案是 B。本题考查公共政策与经济增长。投资税收抵免等鼓励资本形成的政策有助于长期增长。 因此“Investment tax credits”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-155"}, {"id": "ma-source-MACRO-157", "topic": "6.1", "unit": 6, "skill": "concept", "stem": "A country can have an increased surplus in its balance of trade as a result of", "options": [{"key": "A", "text": "an increase in domestic inflation", "error": "C2"}, {"key": "B", "text": "declining imports and rising exports", "error": null}, {"key": "C", "text": "higher tariffs imposed by its trading partners", "error": "C2"}, {"key": "D", "text": "an increase in capital inflow", "error": "C2"}, {"key": "E", "text": "an appreciating currency", "error": "C2"}], "correct": "B", "explanation": "Exports minus imports rises when exports rise and imports fall.", "zh": "正确答案是 B。本题考查国际收支账户。贸易余额改善来自出口上升或进口下降。 因此“declining imports and rising exports”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-157"}, {"id": "ma-source-MACRO-158", "topic": "6.2", "unit": 6, "skill": "concept", "stem": "When the United States dollar appreciates against the euro, which of the following will most likely happen?", "options": [{"key": "A", "text": "European firms will pay fewer euros for equipment purchased from the United States.", "error": "C2"}, {"key": "B", "text": "European products will become more expensive for United States consumers.", "error": "C2"}, {"key": "C", "text": "United States tourists will pay fewer dollars for trips to Europe.", "error": null}, {"key": "D", "text": "The European trade deficit will increase.", "error": "C2"}, {"key": "E", "text": "The United States trade deficit will decrease.", "error": "C2"}], "correct": "C", "explanation": "An appreciated dollar buys more euros, reducing the dollar cost of unchanged euro-priced travel.", "zh": "正确答案是 C。本题考查汇率。本币升值意味着本国居民用本币购买外国货币或商品更便宜。 因此“United States tourists will pay fewer dollars for trips to Europe.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-158"}, {"id": "ma-source-MACRO-163", "topic": "6.3", "unit": 6, "skill": "concept", "stem": "Flexible exchange rates are determined by:", "options": [{"key": "A", "text": "Central banks of the nations", "error": "C2"}, {"key": "B", "text": "Governments of the nations", "error": "C2"}, {"key": "C", "text": "International agreements", "error": "C2"}, {"key": "D", "text": "Forces of supply and demand", "error": null}, {"key": "E", "text": "Businesses of the nations", "error": "C2"}], "correct": "D", "explanation": "In a flexible exchange-rate system, currency demand and supply determine the rate.", "zh": "正确答案是 D。本题考查外汇市场。浮动汇率由外汇市场的供给与需求决定。 因此“Forces of supply and demand”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-163"}, {"id": "ma-source-MACRO-166", "topic": "6.5", "unit": 6, "skill": "concept", "stem": "If the exchange rate between the United States dollar($) and the British pound (£) changed from $2 per £l to $3 per £l,and domestic prices in both countries stayed the same,then the United States dollar would", "options": [{"key": "A", "text": "depreciate, making United States imports from Britain more expensive", "error": null}, {"key": "B", "text": "depreciate, making United States imports from Britain cheaper", "error": "C2"}, {"key": "C", "text": "appreciate, making United States imports from Britain more expensive", "error": "C2"}, {"key": "D", "text": "appreciate, making United States imports from Britain cheaper", "error": "C2"}, {"key": "E", "text": "purchase 3 times more British goods than before the change occurred", "error": "C2"}], "correct": "A", "explanation": "More dollars per pound means dollar depreciation; unchanged pound-priced imports cost more dollars.", "zh": "正确答案是 A。本题考查外汇市场变化与净出口。本币贬值使本国产品对外国人更便宜，通常增加出口、减少进口。 因此“depreciate, making United States imports from Britain more expensive”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-166"}, {"id": "ma-source-MACRO-167", "topic": "6.5", "unit": 6, "skill": "concept", "stem": "Assume the countries of Ornania and Kumbagi are major trading partners. Ornania is currently in long-run macroeconomic equilibrium. As a result of a recession in its economy, Kumbagi decreases its demand for goods produced in Ornania. Which of the following will occur in Ornania in the short run?", "options": [{"key": "A", "text": "The aggregate demand curve will shift to the right, causing the actual rate of unemployment to exceed the natural rate of unemployment.", "error": "C2"}, {"key": "B", "text": "The aggregate demand curve will shift to the left, resulting in an inflationary gap.", "error": "C2"}, {"key": "C", "text": "The aggregate demand curve will shift to the left, resulting in a recessionary gap.", "error": null}, {"key": "D", "text": "The short-run aggregate supply curve will shift to the left, resulting in an inflationary gap.", "error": "C2"}, {"key": "E", "text": "The short-run aggregate supply curve will shift to the left, resulting in a recessionary gap", "error": "C2"}], "correct": "C", "explanation": "Falling foreign purchases reduce Ornania’s net exports and AD, creating a recessionary gap from initial long-run equilibrium.", "zh": "正确答案是 C。本题考查外汇市场变化与净出口。本币贬值使本国产品对外国人更便宜，通常增加出口、减少进口。 因此“The aggregate demand curve will shift to the left, resulting in a recessionary gap.”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-167"}, {"id": "ma-source-MACRO-168", "topic": "6.6", "unit": 6, "skill": "concept", "stem": "If the real interest rate in the United States increases relative to that of the rest of the world, capital should flow", "options": [{"key": "A", "text": "into the United States and the dollar will depreciate", "error": "C2"}, {"key": "B", "text": "into the United States and the dollar will appreciate", "error": null}, {"key": "C", "text": "out of the United States and the dollar will depreciate", "error": "C2"}, {"key": "D", "text": "out of the United States and the dollar will appreciate", "error": "C2"}, {"key": "E", "text": "out of the United States and the value of the dollar will not change", "error": "C2"}], "correct": "B", "explanation": "Higher relative real returns attract financial inflows and raise demand for dollars, other things equal.", "zh": "正确答案是 B。本题考查实际利率与国际资本流动。实际利率相对上升会吸引资本流入，推动本币升值。 因此“into the United States and the dollar will appreciate”最符合题干。", "target": 90, "source": "Adapted from your AP Macro practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/macro-MCQ-practice/", "sourceId": "MACRO-168"}];
